solutionCode:
public class Solution {
    static final class Ponto {
        final int x, y;
        Ponto(int x, int y) { this.x = x; this.y = y; }

        @Override public boolean equals(Object o) {
            if (this == o) return true;
            if (!(o instanceof Ponto p)) return false;
            return x == p.x && y == p.y;
        }

        // 31 * h + campo: o mesmo esquema de String.hashCode, espalha bem combinações pequenas.
        @Override public int hashCode() {
            return 31 * x + y;
        }
    }
}

