import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

import java.util.*;

class SolutionTest {
    @Test void iguaisPorValor() {
        var a = new Solution.Ponto(1, 2);
        var b = new Solution.Ponto(1, 2);
        assertEquals(a, b);
        assertEquals(b, a);
        assertEquals(a.hashCode(), b.hashCode());
        assertNotEquals(a, new Solution.Ponto(2, 1));
        assertNotEquals(a, null);
        assertNotEquals(a, "ponto");
    }

    @Test void funcionaComoChave() {
        Set<Solution.Ponto> s = new HashSet<>();
        s.add(new Solution.Ponto(3, 4));
        assertTrue(s.contains(new Solution.Ponto(3, 4)));
        Map<Solution.Ponto, String> m = new HashMap<>();
        m.put(new Solution.Ponto(0, 0), "origem");
        assertEquals("origem", m.get(new Solution.Ponto(0, 0)));
    }

    @Test void hashEspalha() {
        Set<Integer> hashes = new HashSet<>();
        for (int x = 0; x < 100; x++) for (int y = 0; y < 100; y++) hashes.add(new Solution.Ponto(x, y).hashCode());
        assertTrue(hashes.size() >= 3000, "só " + hashes.size() + " hashes distintos");
    }
}
